<script>
export default {
  data() {
    return {
      // 用户信息
      userInfo: {
        avatar: '',
        nickname: '',
        intro: '这个人很懒，什么都没有留下',
        isMember: false,
        isLogin: false
      },
      
      // 用户统计数据
      userStats: {
        orderCount: 5,
        pendingPayment: 1,
        pendingReceipt: 2,
        afterSale: 0
      },
      
      // 资产数据
      assets: {
        couponCount: 3,
        integral: 1250,
        balance: 156.80,
        giftCard: 1
      },
      
      // 常用功能列表
      functions: [
        { id: 1, name: '我的收藏', icon: 'heart-filled', color: '#FF4D4F', bgColor: '#FFF1F0', path: '/pages/my/favorite/favorite' },
        { id: 2, name: '我的足迹', icon: 'eye-filled', color: '#1890FF', bgColor: '#E6F7FF', path: '/pages/my/history/history' },
        { id: 3, name: '我的地址', icon: 'location-filled', color: '#52C41A', bgColor: '#F6FFED', path: '/pages/my/address/address' },
        { id: 4, name: '我的客服', icon: 'headphones', color: '#722ED1', bgColor: '#F9F0FF', path: '/pages/service/service' },
        { id: 5, name: '我的评价', icon: 'compose', color: '#FA8C16', bgColor: '#FFF7E6', path: '/pages/my/comment/comment' },
        { id: 6, name: '帮助中心', icon: 'help', color: '#13C2C2', bgColor: '#E6FFFB', path: '/pages/help/help' }
      ],
      
      // 我的服务列表
      services: [
        { id: 1, name: '会员中心', icon: 'vip', color: '#FF6B35', bgColor: '#FFF2E8', path: '/pages/vip/vip' },
        { id: 2, name: '积分商城', icon: 'shop', color: '#FF4D4F', bgColor: '#FFF1F0', path: '/pages/integral-mall/mall' },
        { id: 3, name: '我的发票', icon: 'paperplane', color: '#1890FF', bgColor: '#E6F7FF', path: '/pages/my/invoice/invoice' },
        { id: 4, name: '我的预约', icon: 'calendar', color: '#52C41A', bgColor: '#F6FFED', path: '/pages/my/appointment/appointment' }
      ],
      
      // 工具与服务
      tools: [
        { id: 1, name: '消息中心', icon: 'chat', color: '#FF6B35', bgColor: '#FFF2E8', path: '/pages/message/message' },
        { id: 2, name: '设置', icon: 'gear-filled', color: '#1890FF', bgColor: '#E6F7FF', path: '/pages/setting/setting' },
        { id: 3, name: '关于我们', icon: 'info', color: '#52C41A', bgColor: '#F6FFED', path: '/pages/about/about' },
        { id: 4, name: '意见反馈', icon: 'email', color: '#722ED1', bgColor: '#F9F0FF', path: '/pages/feedback/feedback' }
      ],
      
      // 页面滚动距离，用于头部背景效果
      scrollTop: 0
    }
  },
  
  computed: {
    // 头部样式，根据滚动距离变化
    headerStyle() {
      const opacity = Math.min(this.scrollTop / 100, 0.9)
      return {
        background: `linear-gradient(135deg, rgba(255, 107, 53, ${0.9 - opacity}), rgba(255, 77, 79, ${0.9 - opacity}))`
      }
    }
  },
  
  onLoad() {
    this.checkLoginStatus()
    this.getUserData()
  },
  
  onPageScroll(e) {
    this.scrollTop = e.scrollTop
  },
  
  onShow() {
    // 页面显示时刷新用户数据
    this.getUserData()
  },
  
  methods: {
    // 检查登录状态
    checkLoginStatus() {
      const token = uni.getStorageSync('token')
      if (token) {
        this.userInfo.isLogin = true
        // 这里可以请求接口获取用户信息
        this.getUserInfoFromStorage()
      } else {
        this.userInfo.isLogin = false
        this.userInfo.nickname = '点击登录'
        this.userInfo.avatar = '/static/images/default-avatar.png'
      }
    },
    
    // 从缓存获取用户信息
    getUserInfoFromStorage() {
      const userInfo = uni.getStorageSync('userInfo')
      if (userInfo) {
        this.userInfo = { ...this.userInfo, ...userInfo }
      }
    },
    
    // 获取用户数据
    async getUserData() {
      if (!this.userInfo.isLogin) return
      
      // 模拟API请求
      try {
        // 在实际项目中，这里应该调用API接口
        // const res = await this.$api.user.getUserStats()
        // this.userStats = res.stats
        // this.assets = res.assets
        
        // 模拟数据更新
        console.log('获取用户数据成功')
      } catch (error) {
        console.error('获取用户数据失败:', error)
      }
    },
    
    // 处理头像点击
    handleAvatarClick() {
      if (!this.userInfo.isLogin) {
        this.$refs.loginPopup.open()
        return
      }
      
      // 已登录，跳转到个人资料页
      this.navigateTo('/pages/my/profile/profile')
    },
    
    // 处理登录
    handleLogin() {
      this.$refs.loginPopup.open()
    },
    
    // 处理获取用户信息
    async handleGetUserInfo(e) {
      if (e.detail.userInfo) {
        // 用户授权成功
        try {
          // 这里应该调用登录接口
          // const res = await this.$api.user.login(e.detail)
          
          // 模拟登录成功
          const userInfo = {
            avatar: e.detail.userInfo.avatarUrl,
            nickname: e.detail.userInfo.nickName,
            isLogin: true,
            isMember: false
          }
          
          // 保存用户信息
          uni.setStorageSync('userInfo', userInfo)
          uni.setStorageSync('token', 'mock-token-' + Date.now())
          
          // 更新本地数据
          this.userInfo = { ...this.userInfo, ...userInfo }
          
          // 关闭登录弹窗
          this.closeLoginPopup()
          
          // 获取用户数据
          this.getUserData()
          
          uni.showToast({
            title: '登录成功',
            icon: 'success'
          })
        } catch (error) {
          uni.showToast({
            title: '登录失败',
            icon: 'error'
          })
        }
      } else {
        // 用户拒绝授权
        uni.showToast({
          title: '授权失败',
          icon: 'error'
        })
      }
    },
    
    // 关闭登录弹窗
    closeLoginPopup() {
      this.$refs.loginPopup.close()
    },
    
    // 处理功能点击
    handleFunctionClick(item) {
      if (!this.userInfo.isLogin && item.id !== 6) { // 帮助中心不需要登录
        this.$refs.loginPopup.open()
        return
      }
      this.navigateTo(item.path)
    },
    
    // 页面跳转
    navigateTo(path) {
      if (!this.userInfo.isLogin && !this.isPublicPage(path)) {
        this.$refs.loginPopup.open()
        return
      }
      uni.navigateTo({
        url: path
      })
    },
    
    // 判断是否为公开页面（不需要登录）
    isPublicPage(path) {
      const publicPages = ['/pages/help/help', '/pages/about/about', '/pages/agreement/user', '/pages/agreement/privacy']
      return publicPages.includes(path)
    },
    
    // 格式化余额显示
    formatBalance(balance) {
      return '¥' + balance.toFixed(2)
    },
    
    // 处理退出登录
    handleLogout() {
      uni.showModal({
        title: '提示',
        content: '确定要退出登录吗？',
        success: (res) => {
          if (res.confirm) {
            // 清除登录状态
            uni.removeStorageSync('token')
            uni.removeStorageSync('userInfo')
            
            // 重置用户信息
            this.userInfo = {
              avatar: '',
              nickname: '点击登录',
              intro: '',
              isMember: false,
              isLogin: false
            }
            
            // 重置数据
            this.userStats = {
              orderCount: 0,
              pendingPayment: 0,
              pendingReceipt: 0,
              afterSale: 0
            }
            
            this.assets = {
              couponCount: 0,
              integral: 0,
              balance: 0,
              giftCard: 0
            }
            
            uni.showToast({
              title: '已退出登录',
              icon: 'success'
            })
          }
        }
      })
    }
  }
}
</script>

